import { describe, it } from 'node:test';
import {
  GROUPS,
  chapterLine,
  getChapter,
  getGuide,
  jcsBytes,
  neighbours,
  tourProjectionDigest,
  verifyBundle,
  versionStamp,
  type GuideBundle,
} from '../guide';

const FRAMES = new URL('../../public/guide/', import.meta.url).pathname;
const guide = getGuide();
const sha256 = (data: string | Buffer) => createHash('sha256').update(data).digest('hex');
const copy = (): GuideBundle => JSON.parse(JSON.stringify(guide));

describe('canonical bytes match the vynr generator (RFC 8785, spec §7)', () => {
  it('writes numbers in ECMAScript form, the fixtures build_guide.py tests', () => {
    const fixtures: [number, string][] = [
      [0, '0'], [-0, '0'], [1, '1'], [0.5, '0.5'], [0.00001, '0.00001'], [0.000001, '0.000001'],
      [1e-7, '1e-7'], [9.9e-7, '9.9e-7'], [9.99e20, '999000000000000000000'], [1e21, '1e+21'],
      [1.5e21, '1.5e+21'], [0.2, '0.2'], [0.959, '0.959'], [123.456, '123.456'], [-0.25, '-0.25'],
      [1.2345e-8, '1.2345e-8'], [5e-324, '5e-324'], [100, '100'], [3, '3'],
    ];
    for (const [value, expected] of fixtures) assert.equal(jcsBytes(value), expected, String(value));
  });

  it('sorts keys, drops whitespace and escapes only what JSON requires', () => {
    assert.equal(jcsBytes({ b: 1, a: [0, 'x"y'] }), '{"a":[0,"x\\"y"],"b":1}');
    assert.equal(jcsBytes('\u0001/→'), '"\\u0001/→"');
    assert.equal(jcsBytes([true, false, null]), '[true,false,null]');
  });

  it('refuses values JSON cannot carry', () => {
    assert.throws(() => jcsBytes(Number.NaN), /non-finite/);
    assert.throws(() => jcsBytes(undefined), /unsupported/);
  });
});

describe('the bundle is the one vynr generated', () => {
  it('reproduces its contentHash over the chapters and images', () => {
    assert.equal(guide.contentHash, sha256(jcsBytes({ chapters: guide.chapters, images: guide.images })));
  });

  it('carries the bootstrap equality digest exactly when it was bootstrapped', () => {
    if (guide.guideSourceCommit === guide.appSourceCommit) {
      assert.equal(guide.bootstrapEqualityDigest, null);
    } else {
      assert.equal(guide.bootstrapEqualityDigest, tourProjectionDigest(guide));
    }
    assert.equal(tourProjectionDigest(guide), '8b917f987240761775f46bec3b8552730d527fe66a9a30c7583be845ad707181');
  });

  it('stamps the version its release tag names', () => {
    assert.match(guide.guideSourceCommit, /^[0-9a-f]{40}$/);
    assert.match(guide.appSourceCommit, /^[0-9a-f]{40}$/);
    const tag = guide.describes.match(/^v(\d+\.\d+(?:\.\d+)?)-build\d+-source$/);
    assert.ok(tag, guide.describes);
    assert.equal(guide.appVersion, tag[1]);
    assert.equal(versionStamp(guide), `Guide for vynr ${guide.appVersion}`);
  });

  it('ships every frame it lists, byte for byte, and lists every frame a tour uses', () => {
    for (const [name, hash] of Object.entries(guide.images)) {
      assert.equal(sha256(readFileSync(FRAMES + name)), hash, name);
    }
    const used = new Set(guide.chapters.flatMap(c => c.tour?.shots.map(s => s.file) ?? []));
    assert.deepEqual([...used].sort(), Object.keys(guide.images).sort());
  });

  it('rejects a bundle edited by hand', () => {
    const tampered = copy();
    tampered.chapters[0].tour!.shots[0].callouts[0].text += ' (edited)';
    assert.throws(() => verifyBundle(tampered, FRAMES), /contentHash/);
  });

  it('rejects a frame that does not match its hash', () => {
    const tampered = copy();
    const name = Object.keys(tampered.images)[0];
    tampered.images[name] = '0'.repeat(64);
    assert.throws(() => verifyBundle(tampered, FRAMES), new RegExp(name.replace('.', '\\.')));
  });

  it('names a malformed bundle instead of failing on its shape', () => {
    const shape = copy() as unknown as Record<string, unknown>;
    shape.chapters = 'not a list';
    assert.throws(() => verifyBundle(shape as unknown as GuideBundle, FRAMES), /chapters: must be a list/);
  });

  it('rejects an unknown group and a stamp that disagrees with its tag', () => {
    const group = copy();
    group.chapters[0].group = 'misc';
    assert.throws(() => verifyBundle(group, FRAMES), /group/);
    const version = copy();
    version.appVersion = '9.9';
    assert.throws(() => verifyBundle(version, FRAMES), /appVersion/);
  });
});

describe('chapters keep the source order and its groups', () => {
  it('lists the twelve tour chapters in tour order, with the web-only chapters in their groups', () => {
    assert.deepEqual(guide.chapters.map(c => c.id), [
      'move', 'jump', 'two-fingers', 'back-across', 'places', 'hold', 'pinch',
      'add', 'filters', 'follow', 'storage', 'time-lens', 'journal', 'keep-safe',
    ]);
    assert.deepEqual(guide.chapters.filter(c => c.tour === null).map(c => c.id), ['storage', 'keep-safe']);
    const groups = guide.chapters.map(c => c.group);
    assert.deepEqual(groups.filter((g, i) => g !== groups[i - 1]), GROUPS.map(g => g.id),
      'each group is one contiguous run, in GROUPS order');
    const known: readonly string[] = GROUPS.map(g => g.id);
    for (const chapter of guide.chapters) assert.ok(known.includes(chapter.group), chapter.id);
  });

  it('gives each chapter its index line and its neighbours', () => {
    const move = getChapter('move')!;
    assert.equal(chapterLine(move), move.tour!.message);
    assert.equal(getChapter('nope'), undefined);
    assert.deepEqual(neighbours('move'), { previous: undefined, next: getChapter('jump') });
    assert.deepEqual(neighbours('storage'), { previous: getChapter('follow'), next: getChapter('time-lens') });
    assert.deepEqual(neighbours('keep-safe'), { previous: getChapter('journal'), next: undefined });
    const storage = getChapter('storage')!;
    assert.equal(chapterLine(storage), storage.summary, 'a web-only chapter leads with its summary');
  });
});
import { createHash } from 'crypto'
import fs from 'fs'
import path from 'path'
import { displaySpace, jpegSize, type Size } from './guide-overlay'

// The Guide to vynr is written once, in vynr's guide/chapters (SJAM-1041). vynr's
// scripts/build_guide.py writes the generated bundle this module reads:
// content/guide/guide.json and public/guide/*.jpg. Neither is ever edited here
// (ADR-WEB-0001 ADDENDUM-002). The bundle is verified on load, so a hand edit, a stale frame
// or a stamp that disagrees with its release fails the build instead of reaching the site.
// Spec: vynr docs/superpowers/specs/2026-10-21-guide-single-source-design.md §6–§7.
const BUNDLE_PATH = path.join(process.cwd(), 'content/guide/guide.json')
const FRAMES_DIR = path.join(process.cwd(), 'public/guide')
const NAME = 'content/guide/guide.json'

/** The /guide index groups, in index order (spec §6). A group with no chapters is not shown. */
export const GROUPS = [
  { id: 'getting-around', heading: 'Getting around' },
  { id: 'your-wines', heading: 'Your wines' },
  { id: 'time-and-memory', heading: 'Time and memory' },
  { id: 'your-data', heading: 'Your data' },
] as const

const TAG = /^v(\d+\.\d+(?:\.\d+)?)-build\d+-source$/
const SHA = /^[0-9a-f]{40}$/
const DIGEST = /^[0-9a-f]{64}$/

export interface Trace {
  fingers: 1 | 2
  from: [number, number]
  to: [number, number]
  hold: boolean
  motion: 'parallel' | 'spread' | 'pinch' | 'hold'
}

export interface Callout {
  number: number
  text: string
  /** x, y, width, height, normalised to the shot. */
  target: [number, number, number, number]
  badge: [number, number]
  trace: Trace | null
}

export interface Shot {
  file: string
  alt: string
  callouts: Callout[]
}

/** A tour page exactly as the app's FeatureTourCatalog.pages holds it (spec §7 projection). */
export interface Tour {
  id: string
  title: string
  message: string
  shots: Shot[]
}

export interface Chapter {
  id: string
  title: string
  group: string
  summary: string | null
  tour: Tour | null
  /** Raw Markdown: the web-only depth. */
  body: string
}

export interface GuideBundle {
  guideSourceCommit: string
  appSourceCommit: string
  describes: string
  appVersion: string
  bootstrapEqualityDigest: string | null
  contentHash: string
  chapters: Chapter[]
  images: Record<string, string>
}

/** RFC 8785 canonical JSON: keys sorted by UTF-16 code unit, no whitespace, ES number form. */
export function jcsBytes(value: unknown): string {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return JSON.stringify(value)
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error(`canonical bytes: non-finite number ${value}`)
    return JSON.stringify(value)
  }
  if (Array.isArray(value)) return `[${value.map(jcsBytes).join(',')}]`
  if (typeof value === 'object') {
    const entries = Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${jcsBytes((value as Record<string, unknown>)[key])}`)
    return `{${entries.join(',')}}`
  }
  throw new Error(`canonical bytes: unsupported value ${String(value)}`)
}

export function sha256Hex(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex')
}

/** The digest that proves the bundle's tour equals the described build's tour (spec §7). */
export function tourProjectionDigest(bundle: GuideBundle): string {
  return sha256Hex(jcsBytes(bundle.chapters.flatMap(c => (c.tour ? [c.tour] : []))))
}

/** Every rule the bundle must meet; throws naming the field. */
export function verifyBundle(bundle: GuideBundle, framesDir: string): void {
  const fail = (field: string, problem: string): never => {
    throw new Error(`${NAME}: ${field}: ${problem}`)
  }
  if (!Array.isArray(bundle.chapters)) fail('chapters', 'must be a list')
  if (typeof bundle.images !== 'object' || bundle.images === null) fail('images', 'must be an object')
  if (!SHA.test(bundle.guideSourceCommit)) fail('guideSourceCommit', 'not a 40-hex commit')
  if (!SHA.test(bundle.appSourceCommit)) fail('appSourceCommit', 'not a 40-hex commit')
  const tag = bundle.describes.match(TAG)
  if (!tag) return fail('describes', `${bundle.describes} is not a v<version>-build<N>-source tag`)
  if (bundle.appVersion !== tag[1]) fail('appVersion', `${bundle.appVersion} disagrees with ${bundle.describes}`)

  const groups: readonly string[] = GROUPS.map(g => g.id)
  const ids = new Set<string>()
  for (const chapter of bundle.chapters) {
    if (ids.has(chapter.id)) fail('chapters', `duplicate id ${chapter.id}`)
    ids.add(chapter.id)
    if (!groups.includes(chapter.group)) fail(`${chapter.id}.group`, `unknown group ${chapter.group}`)
    if (chapter.tour === null && !chapter.summary) fail(`${chapter.id}.summary`, 'a chapter without a tour needs a summary')
    if (chapter.tour !== null && chapter.tour.id !== chapter.id) fail(`${chapter.id}.tour.id`, 'differs from the chapter id')
  }

  const used = new Set(bundle.chapters.flatMap(c => c.tour?.shots.map(s => s.file) ?? []))
  for (const name of used) if (!(name in bundle.images)) fail('images', `${name} is used by a tour but not listed`)
  for (const [name, hash] of Object.entries(bundle.images)) {
    if (!used.has(name)) fail('images', `${name} is listed but no tour uses it`)
    const file = path.join(framesDir, name)
    if (!fs.existsSync(file)) fail('images', `${name} is missing from public/guide`)
    if (sha256Hex(fs.readFileSync(file)) !== hash) fail('images', `${name} does not match its sha256`)
  }

  const content = sha256Hex(jcsBytes({ chapters: bundle.chapters, images: bundle.images }))
  if (content !== bundle.contentHash) fail('contentHash', `does not reproduce (computed ${content})`)

  const bootstrapped = bundle.guideSourceCommit !== bundle.appSourceCommit
  if (!bootstrapped && bundle.bootstrapEqualityDigest !== null) {
    fail('bootstrapEqualityDigest', 'must be null when the guide and app commits are the same')
  }
  if (bootstrapped) {
    if (bundle.bootstrapEqualityDigest === null || !DIGEST.test(bundle.bootstrapEqualityDigest)) {
      fail('bootstrapEqualityDigest', 'required when the guide and app commits differ')
    }
    if (bundle.bootstrapEqualityDigest !== tourProjectionDigest(bundle)) {
      fail('bootstrapEqualityDigest', 'is not the tour projection digest of this bundle')
    }
  }
}

let cached: GuideBundle | undefined

/** The verified bundle; a bad bundle throws, so `next build` fails rather than render it. */
export function getGuide(): GuideBundle {
  if (!cached) {
    const bundle = JSON.parse(fs.readFileSync(BUNDLE_PATH, 'utf8')) as GuideBundle
    verifyBundle(bundle, FRAMES_DIR)
    cached = bundle
  }
  return cached
}

export function getChapter(id: string): Chapter | undefined {
  return getGuide().chapters.find(c => c.id === id)
}

/** The previous and next chapters in source order. */
export function neighbours(id: string): { previous?: Chapter; next?: Chapter } {
  const chapters = getGuide().chapters
  const index = chapters.findIndex(c => c.id === id)
  return { previous: chapters[index - 1], next: index >= 0 ? chapters[index + 1] : undefined }
}

/** The chapter's one line on the index and in its meta description: the tour message or the summary. */
export function chapterLine(chapter: Chapter): string {
  return chapter.tour?.message ?? chapter.summary ?? ''
}

export function versionStamp(bundle: GuideBundle): string {
  return `Guide for vynr ${bundle.appVersion}`
}

/** A frame's pixel size, read from the JPEG, and its size in the app's display space. */
export function frameSize(file: string): { pixels: Size; display: Size } {
  const pixels = jpegSize(fs.readFileSync(path.join(FRAMES_DIR, file)))
  const { width, height } = displaySpace(pixels.width, pixels.height)
  return { pixels, display: { width, height } }
}

import { chapterLine, frameSize, type Chapter } from "@/lib/guide";
import { render } from "@/lib/markdown-source";
import ShotFrame from "./ShotFrame";

/**
 * One chapter as a story section (spec §6). The server markup is the whole page in reading
 * order: each shot inline, then its steps. On wide screens GuideStoryEnhancer pins the phone
 * column beside the steps and lights the step being read; without it this order stands.
 */
export default function ChapterStory({ chapter, index, headingLevel = 2, eagerFirstShot = false }: {
  chapter: Chapter;
  index: number;
  headingLevel?: 1 | 2;
  /** The page's first shot loads at once; the rest are lazy. */
  eagerFirstShot?: boolean;
}) {
  const Heading = headingLevel === 1 ? "h1" : "h2";
  const shots = chapter.tour?.shots ?? [];
  const frames = shots.map((shot) => frameSize(shot.file));
  const body = chapter.body.trim();

  return (
    <section id={chapter.id} className="guide-chapter" data-guide-story="" aria-labelledby={`${chapter.id}-title`}>
      <p className="guide-kicker">Chapter {index + 1}</p>
      <Heading id={`${chapter.id}-title`} className="guide-chapter-title">{chapter.title}</Heading>
      <p className="guide-lede">{chapterLine(chapter)}</p>

      {shots.length > 0 && (
        <div className="guide-story">
          <div className="guide-steps">
            {shots.map((shot, s) => (
              <div key={shot.file} className="guide-shot-group">
                <div className="guide-inline-shot">
                  <ShotFrame shot={shot} pixels={frames[s].pixels} display={frames[s].display} eager={eagerFirstShot && s === 0} />
                </div>
                <ol className="guide-step-list" start={shot.callouts[0].number}>
                  {shot.callouts.map((callout) => (
                    <li key={callout.number} value={callout.number} className="guide-step"
                      data-shot={s} data-n={callout.number}>
                      <span className="guide-badge" aria-hidden="true">{callout.number}</span>
                      <span>{callout.text}</span>
                    </li>
                  ))}
                </ol>
              </div>
            ))}
          </div>
          <div className="guide-phone-col" aria-hidden="true">
            <div className="guide-phone">
              <div className="guide-screen">
                {shots.map((shot, s) => (
                  <div key={shot.file} className={s === 0 ? "guide-phone-shot is-shown" : "guide-phone-shot"} data-shot={s}>
                    <ShotFrame shot={shot} pixels={frames[s].pixels} display={frames[s].display} decorative
                      eager={eagerFirstShot && s === 0} />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {body && <div className="prose guide-body" dangerouslySetInnerHTML={{ __html: render(body) }} />}
    </section>
  );
}
