import fs from 'fs'
import path from 'path'
import { assertUniqueIds, readSource, render, slug, splitAt } from './markdown-source'

// VYNR-PLUS.md at the repository root is the single public source for /vynr-plus. It restates
// the V1 free/vynr+ boundary (ADR-0018 ADDENDUM SJAM-591 D3) and must never extend it.
const PLANS_PATH = path.join(process.cwd(), 'VYNR-PLUS.md')
const NAME = 'VYNR-PLUS.md'

export interface ComparisonRow {
  id: string
  area: string
  freeHtml: string
  plusHtml: string
}

export interface PlansSection {
  id: string
  title: string
  html: string
  /** Present when the section is a side-by-side comparison. */
  rows?: ComparisonRow[]
}

export interface Plans {
  title: string
  summary: string
  introHtml: string
  sections: PlansSection[]
}

// A comparison row is exactly two list items: "- **vynr:** …" then "- **vynr+:** …".
const ROW = /^- \*\*vynr:\*\* (.+)\n- \*\*vynr\+:\*\* (.+)$/

function parseRow(area: string, body: string): ComparisonRow | null {
  const match = body.trim().match(ROW)
  return match ? { id: slug(area), area, freeHtml: render(match[1]), plusHtml: render(match[2]) } : null
}

export function parsePlans(raw: string): Plans {
  const document = readSource(raw, NAME)
  const sections = document.sections.map(({ heading, body }): PlansSection => {
    const { preamble, parts } = splitAt(body, '### ')
    const rows = parts.map(part => parseRow(part.heading, part.body))
    const isComparison = parts.length > 0 && rows.every(row => row !== null)
    if (!isComparison && parts.length > 0 && rows.some(row => row !== null)) {
      throw new Error(`${NAME}: "${heading}" mixes comparison rows with other subsections`)
    }
    return isComparison
      ? { id: slug(heading), title: heading, html: render(preamble), rows: rows as ComparisonRow[] }
      : { id: slug(heading), title: heading, html: render(body) }
  })
  assertUniqueIds(sections.map(s => s.id), NAME)
  return { title: document.title, summary: document.summary, introHtml: render(document.preamble), sections }
}

export function getPlans(): Plans {
  return parsePlans(fs.readFileSync(PLANS_PATH, 'utf8'))
}

import { remark } from 'remark'
import html from 'remark-html'

// Shared reading of the site's single-source public documents (ROADMAP.md, VYNR-PLUS.md).
// Each file is GitHub-readable as-is; these helpers split it on heading lines and render
// each part through remark, so a page lays the document out without carrying its words.

// Links to the site itself are written absolutely so they work on GitHub; on the site they are local.
const SITE_LINK = /href="https:\/\/(?:www\.)?vynr\.app(\/[^"]*)?"/g

interface MarkdownNode {
  type: string
  children?: MarkdownNode[]
}

/** Whether the parsed markdown tree contains a node of `type` anywhere, at any depth. */
function hasNode(node: MarkdownNode, type: string): boolean {
  return node.type === type || (node.children ?? []).some(child => hasNode(child, type))
}

export function slug(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

export function render(markdown: string): string {
  const out = String(remark().use(html).processSync(markdown.trim()))
  return out.replace(SITE_LINK, (_, path: string | undefined) => `href="${path ?? '/'}"`)
}

export interface MarkdownPart {
  heading: string
  body: string
}

/** Splits `markdown` at every line starting with `marker` (e.g. "## "), returning the preamble and the parts. */
export function splitAt(markdown: string, marker: string): { preamble: string; parts: MarkdownPart[] } {
  const [preamble, ...rest] = markdown.split(new RegExp(`^${marker}`, 'm'))
  return {
    preamble,
    parts: rest.map(chunk => {
      const newline = chunk.indexOf('\n')
      return newline === -1
        ? { heading: chunk.trim(), body: '' }
        : { heading: chunk.slice(0, newline).trim(), body: chunk.slice(newline + 1) }
    }),
  }
}

export interface SourceDocument {
  title: string
  /** The first paragraph after the title as plain text, for the page's meta description. */
  summary: string
  /** Everything between the title and the first "## " heading. */
  preamble: string
  /** The "## " sections, in order. */
  sections: MarkdownPart[]
}

/**
 * Reads a public source file, refusing anything the split-and-render approach cannot carry
 * faithfully. `name` prefixes every error so a failed build names the file to fix.
 */
export function readSource(raw: string, name: string): SourceDocument {
  const markdown = raw.replace(/\r\n?/g, '\n')
  // The source is split on heading lines; a fenced block could hide a "## " line and tear
  // the fence apart. These documents have no use for code, so refuse it rather than guess.
  if (/^\s*(?:```|~~~)/m.test(markdown)) throw new Error(`${name}: fenced code blocks are not supported`)
  // Each part renders on its own, so a reference-style link definition in one part would not
  // resolve in another. Inline links only.
  if (hasNode(remark().parse(markdown), 'definition')) {
    throw new Error(`${name}: use inline links, not reference-style definitions`)
  }

  const titleMatch = markdown.match(/^# (.+)$/m)
  if (!titleMatch) throw new Error(`${name}: missing "# " title`)
  const afterTitle = markdown.slice(markdown.indexOf(titleMatch[0]) + titleMatch[0].length)
  const { preamble, parts } = splitAt(afterTitle, '## ')

  const summary = preamble.trim().split(/\n\s*\n/)[0]?.replace(/\s+/g, ' ').trim() ?? ''
  if (!summary) throw new Error(`${name}: the intro must open with a summary paragraph`)

  return { title: titleMatch[1].trim(), summary, preamble, sections: parts }
}

/** Every id becomes an HTML id and a jump target: each must exist and be unique. */
export function assertUniqueIds(ids: string[], name: string): void {
  for (const id of ids) {
    if (!id) throw new Error(`${name}: a heading produced an empty id; use ASCII letters or digits`)
    if (ids.indexOf(id) !== ids.lastIndexOf(id)) throw new Error(`${name}: duplicate id "${id}"`)
  }
}
# vynr and vynr+

vynr is genuinely useful without paying. vynr+ is for when your wine becomes a collection: unlimited bottles and more cellars, planning beyond six months, Assistant Link, Ask vynr whenever you need it, and richer journal composition and publishing.

## No tiers of truth

Everyone sees the same wine facts, education and drinking curves. vynr+ never shows a better or truer version of your wine. Capturing, correcting, backing up and exporting your own records are never paid, and free never shrinks: no release moves an existing free capability behind vynr+.

## What vynr+ adds

### Unlimited bottles and more cellars

Free vynr holds up to 50 bottles you currently own, counted across all your cellars. Bottles you drink or give away stop counting. vynr+ removes the limit and lets you create additional cellars, for a second home, a storage unit or a collection you keep apart.

### Plan beyond six months

The Time Lens shows your whole history for free, and looks forward six months. vynr+ extends the forward view to your cellar's complete future, so you can see which bottles reach their window years from now and plan what to keep.

### Assistant Link

Assistant Link privately connects your cellar to ChatGPT, Claude or Gemini, so you can ask your own assistant what is ready to drink, what to open with dinner, or what you might be overlooking.

- Your assistant reads a snapshot of your cellar that it cannot change. Tasting notes are never included, and your palate is shared only if you choose.
- vynr can keep the snapshot current as you add, drink and correct bottles, or you can publish it yourself.
- You set it up by pasting a private link into your assistant's custom connector, usually on a computer. It uses the open Model Context Protocol (MCP).
- Listing, revoking and deleting your links stay free on every plan.

### Ask vynr, whenever you need it

Free vynr includes five Ask vynr answers a month, with a visible count. vynr+ removes the monthly count; use it whenever you need guidance, within fair use.

### Richer journal composition and publishing

- Composed journal entries: group entries, add members and extra blocks, and keep a pinned workspace.
- A memorandum PDF and a blog-draft export of your journal.
- Publish a snapshot of your cellar to share by link or QR code, and restore one you revoked.
- Copy wines from a shared cellar into your own.
- Image exports without the vynr watermark.

## Side by side

### Bottles

- **vynr:** Up to 50 bottles you currently own, across all your cellars.
- **vynr+:** Unlimited.

### Cellars

- **vynr:** Keep, switch between, rename, reorganise and delete every cellar you have.
- **vynr+:** Create additional cellars.

### Time Lens

- **vynr:** Your full history, and the next six months.
- **vynr+:** Your full history, and the complete forward horizon.

### Ask vynr

- **vynr:** Five answers a month.
- **vynr+:** No monthly count, within fair use.

### Assistant Link

- **vynr:** List, revoke and delete links.
- **vynr+:** Create and use a link to ChatGPT, Claude or Gemini.

### Journal

- **vynr:** Basic entries with one text and one photo block. Read, correct, rename, link and delete everything you have written.
- **vynr+:** Composed entries, the pinned workspace, and memorandum PDF and blog-draft exports.

### Sharing

- **vynr:** Open and browse shared cellars in the app or on the web. List, revoke and delete cellars you published.
- **vynr+:** Publish a new cellar snapshot, restore a revoked one, and copy shared wines into your own cellar.

### Exports

- **vynr:** A full export of all your data, and image exports with a small vynr watermark.
- **vynr+:** Image exports without the watermark.

## Always free

- Label scanning and every other way to capture a wine.
- The Atlas, producer pages, education, Vynrpedia and search.
- The same wine facts and drinking curves on every plan.
- AI Fix and Cellar Health, which correct vynr's own reading, never use your Ask vynr allowance.
- Correcting any wine's identity and details.
- iCloud backup and restore, and a full export of your data.

## Trying vynr+

- One free month, which starts only when you choose **Start your free month**. Opening, scrolling or trying a vynr+ feature never starts it.
- During the free month there is no charge and no subscription. You see the exact end date, and one reminder a few days before it ends.
- If you subscribe during the free month, billing begins that day.
- One free month per device. If you have held vynr+ before, the subscription is offered instead.
- vynr+ is a monthly or yearly subscription through the App Store, which shows the price in your currency.

## If vynr+ ends

- Nothing is deleted. Every bottle, cellar, journal entry and note stays.
- Above 50 bottles, you keep everything; you cannot add owned bottles until you are below the limit.
- You can still switch between, rename, reorganise and delete all your cellars.
- Cellars you published stay viewable until their expiry, or until you revoke or delete them. Publishing a new one needs vynr+.
- Assistant Link pauses, and you can still revoke or delete it. Renewing restores it, but never undoes a revoke.
- In the journal, reading, correcting, renaming, linking, removing and deleting stay free. Composing new grouped entries needs vynr+.

> Questions about a subscription? [Support](https://vynr.app/support) covers managing, cancelling and refunds.
